package com.ruoyi.hexu;
import java.util.*;
import java.sql.Timestamp;
import static com.ruoyi.hexu.HexuStore.*;
import static com.ruoyi.hexu.BusinessException.require;

public final class HexuPointRisk {
 private final HexuStore db;public HexuPointRisk(HexuStore db){this.db=db;}
 public static void validate(Map<String,Object>b){if(bool(b,"frequencyEnabled")){require(number(b,"dailyCount")>0&&number(b,"dailyCount")<=10000,"每日次数须为1至10000");require(number(b,"windowCount")>0&&number(b,"windowCount")<=number(b,"dailyCount"),"短时次数须为正数且不超过每日次数");require(number(b,"windowSeconds")>=10&&number(b,"windowSeconds")<=86400,"短时窗口须为10至86400秒");}}
 /** Caller holds both account locks. A blocked result commits only the risk record, never a debit. */
 public Map<String,Object> preflight(Actor actor,long scope){Map<String,Object>account=db.one("select * from hx_points where shop_id=? and member_id=?",scope,actor.id);if(bool(account,"frozen"))return map("blocked",true,"reason","积分账户已冻结，请等待复核","debit",0,"credit",0);Map<String,Object>rule=db.config(scope,"points_risk");if(!bool(rule,"frequencyEnabled"))return null;long daily=db.jdbc().queryForObject("select count(*) from hx_point_log where shop_id=? and member_id=? and kind='TRANSFER_OUT' and created_at>=?",Long.class,scope,actor.id,Timestamp.valueOf(java.time.LocalDate.now().atStartOfDay())),recent=db.jdbc().queryForObject("select count(*) from hx_point_log where shop_id=? and member_id=? and kind='TRANSFER_OUT' and created_at>=?",Long.class,scope,actor.id,new Timestamp(System.currentTimeMillis()-number(rule,"windowSeconds")*1000));if(daily<number(rule,"dailyCount")&&recent<number(rule,"windowCount"))return null;String reason=daily>=number(rule,"dailyCount")?"达到每日积分转赠次数上限":"短时积分转赠过于频繁";require(bool(rule,"autoFreeze"),reason+"，请稍后重试");String id=id("RISK");db.jdbc().update("update hx_points set frozen=true where shop_id=? and member_id=?",scope,actor.id);Map<String,Object>snapshot=new LinkedHashMap<>(rule);snapshot.put("dailyObserved",daily);snapshot.put("windowObserved",recent);db.jdbc().update("insert into hx_point_risk_case(id,shop_id,member_id,reason,status,rule_json) values(?,?,?,?,'PENDING',?)",id,scope,actor.id,reason,db.json(snapshot));db.audit(actor,scope,"POINT_AUTO_FREEZE",id,account,snapshot);db.message(scope,actor.id,reason+"，账户已冻结待复核",id);return map("blocked",true,"caseId",id,"reason",reason+"，账户已冻结待复核，本次没有扣除积分","debit",0,"credit",0);}
 public Map<String,Object> review(Actor actor,String id,Map<String,Object>b){Map<String,Object>r=db.one("select * from hx_point_risk_case where id=? for update",id);long scope=number(r,"shop_id");if(scope==0)db.platform(actor);else db.manage(actor,scope,"FINANCE");require(Arrays.asList("PENDING","RETAINED").contains(str(r,"status")),"冻结复核已处理");require(actor.staff||number(r,"member_id")!=actor.id,"本人账户的冻结须由另一位管理人员复核");require(str(b,"reason").trim().length()>=2&&str(b,"reason").length()<=500,"请填写复核依据");db.one("select member_id from hx_points where shop_id=? and member_id=? for update",scope,r.get("member_id"));boolean release=bool(b,"release");if(release){require(db.jdbc().queryForObject("select count(*) from hx_point_risk_case where shop_id=? and member_id=? and id<>? and status in ('PENDING','RETAINED')",Long.class,scope,r.get("member_id"),id)==0,"该账户还有其他未解除的冻结事项");db.jdbc().update("update hx_points set frozen=false where shop_id=? and member_id=?",scope,r.get("member_id"));}db.jdbc().update("update hx_point_risk_case set status=?,reviewer=?,review_note=?,reviewed_at=CURRENT_TIMESTAMP where id=?",release?"RELEASED":"RETAINED",(actor.staff?"STAFF:":"MEMBER:")+actor.id,str(b,"reason"),id);db.audit(actor,scope,"POINT_FREEZE_REVIEW",id,r,b);db.message(scope,number(r,"member_id"),release?"积分账户冻结已解除":"积分账户继续冻结，详情请联系商城",id);return db.one("select * from hx_point_risk_case where id=?",id);}
 public Map<String,Object> account(Actor actor,long shop,long member){if(shop==0)db.platform(actor);else db.manage(actor,shop,"FINANCE");Map<String,Object>a=db.pointAccount(shop,member);Map<String,Object>m=db.one("select name from hx_member where id=?",member);Map<String,Object>stats=db.one("select coalesce(sum(case when amount>0 then amount else 0 end),0) gained,coalesce(sum(case when amount<0 and kind not in ('EXPIRE','REFUND_RECLAIM') then -amount else 0 end),0) used from hx_point_log where shop_id=? and member_id=?",shop,member);a.putAll(stats);a.put("name",m.get("name"));a.put("cases",db.jdbc().queryForList("select * from hx_point_risk_case where shop_id=? and member_id=? order by created_at desc",shop,member));return a;}
 public List<Map<String,Object>> transfers(Actor actor,long shop){if(shop==0)db.platform(actor);else db.manage(actor,shop,"FINANCE");return db.jdbc().queryForList("select o.reference_id,o.member_id sender_id,s.name sender_name,i.member_id recipient_id,r.name recipient_name,-o.amount amount,i.amount credit,o.created_at from hx_point_log o join hx_member s on s.id=o.member_id left join hx_point_log i on i.reference_id=o.reference_id and i.shop_id=o.shop_id and i.kind='TRANSFER_IN' left join hx_member r on r.id=i.member_id where o.shop_id=? and o.kind='TRANSFER_OUT' order by o.id desc limit 500",shop);}
 public Map<String,Object> transferSummary(Actor a,long shop){if(shop==0)db.platform(a);else db.manage(a,shop,"FINANCE");return db.one("select count(*) transfers,coalesce(sum(-amount),0) amount from hx_point_log where shop_id=? and kind='TRANSFER_OUT' and created_at>=?",shop,Timestamp.valueOf(java.time.LocalDate.now().atStartOfDay()));}
}
